NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Zechariah'

CHAPTERS = {
    1: {
        1: 'Kahdeksannessa kuussa Daarejaveksen toisena vuotena tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana ja se kuului:',
        2: '" Herra on toden totta vihastunut teidän isiinne.',
        3: 'Sano heille: Näin sanoo Herra Sebaot: Kääntykää luokseni, sanoo Herra Sebaot, niin minäkin käännyn teidän puoleenne, sanoo Herra Sebaot.',
        4: 'Älkää olko isienne kaltaisia, joille aikaisemmat profeetat ovat saarnanneet sanoen: Näin sanoo Herra Sebaot: Kääntykää pois pahoilta teiltänne ja pahoista teoistanne; mutta he eivät kuulleet eivätkä kuunnelleet minua. – Tämä on Herran sana. –',
        5: 'Teidän isänne – missä he ovat? Entä profeetat – ovatko he eläneet iäti?',
        6: 'Mutta minun sanani ja käskyni, jotka olen säätänyt palvelijoilleni profeetoille – eivätkö ne kohdanneet isiänne? He kääntyivät ja sanoivat: \'Niin kuin Herra Sebaot aikoi tehdä meille vaelluksemme ja tekojemme mukaan, niin hän on meille tehnyt.\'"',
        7: 'Kahdentenakymmenentenä neljäntenä päivänä yhdennessätoista kuussa, joka on sebat-kuu, Daarejaveksen toisena vuotena, tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana, ja se kuului:',
        8: 'Näin yöllä, katso, mies ratsasti punaruskealla hevosella ja seisahtui myrttien keskelle laaksoon, ja hänen perässään oli punaruskeita, punaisia ja valkoisia hevosia.',
        9: 'Kysyin: "Mitä nämä ovat, Herra?" Enkeli, joka puhutteli minua, vastasi minulle: "Minä näytän sinulle, mitä ne ovat."',
        10: 'Mies, joka seisoi myrttien keskellä, lausui ja sanoi: "Nämä ovat ne, jotka Herra on lähettänyt maata kuljeskelemaan."',
        11: 'Niin ne vastasivat Herran enkelille, joka seisoi myrttien keskellä, ja sanoivat: "Me olemme maata kuljeskelleet, ja katso, koko maa on alallaan ja rauhassa."',
        12: 'Sitten Herran enkeli lausui ja sanoi: " Herra Sebaot, kuinka kauan sinä viivyt etkä armahda Jerusalemia ja Juudan kaupunkeja, joille olet ollut vihainen nämä seitsemänkymmentä vuotta?"',
        13: 'Herra vastasi enkelille, joka puhutteli minua, ja lausui hyviä, lohdullisia sanoja.',
        14: 'Enkeli, joka puhutteli minua, sanoi minulle: "Saarnaa ja sano: Näin sanoo Herra Sebaot: Kiivailen Jerusalemin ja Siionin puolesta suurella kiivaudella.',
        15: 'Suurella vihalla minä olen vihastunut suruttomiin pakanoihin, jotka, kun minä vähäksi aikaa vihastuin, auttoivat onnettomuutta tapahtumaan.',
        16: 'Sen tähden sanoo Herra näin: Tulen kääntymään Jerusalemin puoleen armahtavaisuudessa. Temppeliäni rakennetaan siellä – tämä on Herran Sebaotin sana – ja mittanuoraa jännitetään Jerusalemin yllä.',
        17: 'Saarnaa vielä ja sano: Näin sanoo Herra Sebaot: Vielä kaupunkini ovat hyvyydestä ylitsevuotavia, ja vielä Herra lohduttaa Siionin ja valitsee taas Jerusalemin."',
    },
    2: {
        1: 'Nostin silmäni ja katsoin. Katso, oli neljä sarvea.',
        2: 'Sanoin enkelille, joka puhutteli minua: "Mitä nämä ovat?" Hän sanoi minulle: "Nämä ovat ne sarvet, jotka ovat hajottaneet Juudan ja Israelin ja Jerusalemin."',
        3: 'Herra näytti minulle neljä seppää.',
        4: 'Kysyin: "Mitä nämä ovat tulleet tekemään?" Niin hän vastasi ja sanoi: "Nuo sarvet ovat ne, jotka ovat hajottaneet Juudan, niin ettei yksikään mies voi nostaa päätään. Mutta nämä ovat tulleet saattamaan ne pelkoon ja heittämään maahan niiden pakanakansojen sarvet, jotka ovat nostaneet sarven Juudan maata vastaan hajottaakseen sen."',
        5: 'Nostin silmäni ja katsoin. Katso, oli mies ja hänen kädessään mittanuora.',
        6: 'Sanoin hänelle: "Mihin sinä olet menossa?" Hän vastasi minulle: "Mittaamaan Jerusalemia nähdäkseni, kuinka leveä ja kuinka pitkä se on oleva."',
        7: 'Katso, sitten enkeli, joka puhutteli minua, lähti liikkeelle, ja toinen enkeli lähti häntä vastaan',
        8: 'ja sanoi tälle: "Juokse, puhu tälle nuorukaiselle ja sano: Jerusalem on oleva avoin asua, sillä niin paljon siinä on ihmisiä ja eläimiä.',
        9: 'Mutta minä olen oleva – tämä on Herran sana – tulimuuri sen ympärillä ja kunnia sen keskellä.',
        10: 'Voi, voi, paetkaa pohjoisesta maasta – tämä on Herran sana! Sillä olen hajottanut teidät neljään taivaan tuuleen. Tämä on Herran sana.',
        11: 'Voi, Siion, pelastaudu, sinä, joka asut tytär Baabelissa!',
        12: 'Sillä näin sanoo Herra Sebaot: Kunniansa tähden hän on lähettänyt minut pakanakansojen luo, jotka ovat teitä saalistaneet. Sillä joka teihin koskee, se koskee hänen silmäteräänsä.',
        13: 'Sillä katso, heilutan kättäni heitä vastaan, ja he joutuvat orjiensa saaliiksi. Tulette tietämään, että Herra Sebaot on lähettänyt minut.',
        14: 'Riemuitse ja iloitse, tytär Siion! Sillä tulen ja asun keskelläsi, sanoo Herra.',
        15: 'Sinä päivänä liittyy paljon pakanoita Herraan, ja he tulevat hänen kansakseen, ja asun keskelläsi, ja tulet tietämään, että Herra Sebaot on lähettänyt minut luoksesi.',
        16: 'Herra ottaa Juudan perintöosakseen pyhässä maassa ja valitsee vielä Jerusalemin.',
        17: 'Vaiti Herran edessä, kaikki liha! Sillä hän on astunut esiin pyhästä asuinsijastaan."',
    },
    3: {
        1: 'Hän näytti minulle ylimmäisen papin Joosuan seisomassa Herran enkelin edessä ja saatanan seisomassa hänen oikealla puolellaan häntä syyttämässä.',
        2: 'Niin Herra sanoi saatanalle: " Herra nuhdelkoon sinua, saatana. Nuhdelkoon sinua Herra, joka on valinnut Jerusalemin. Eikö tämä ole kekäle, joka on tulesta temmattu',
        3: 'Joosua oli puettu saastaisiin vaatteisiin, ja hän seisoi enkelin edessä.',
        4: 'Tämä lausui ja sanoi näin niille, jotka seisoivat hänen edessään: "Riisukaa häneltä pois saastaiset vaatteet." Hän sanoi hänelle: "Katso, olen ottanut sinulta pois pahat tekosi, ja puetan sinut juhlavaatteisiin."',
        5: 'Sanoin: "Pankoot puhtaan turbaanin hänen päähänsä." He panivat puhtaan turbaanin hänen päähänsä ja pukivat hänet vaatteisiin – ja Herran enkeli seisoi siinä.',
        6: 'Sitten Herran enkeli todisti Joosualle sanoen:',
        7: '"Näin sanoo Herra Sebaot: Jos vaellat teitäni ja hoidat säätämäni tehtävät, saat myös tuomita huonettani ja vartioida esikartanoitani, ja annan sinulle pääsyn tässä seisovien joukkoon.',
        8: 'Kuule, Joosua, ylipappi, sinä ja ystäväsi, jotka edessäsi asuvat. Sillä he ovat ihmeellisiä miehiä, koska – katso – annan tulla palvelijani, Vesan.',
        9: 'Sillä katso: kivi, jonka olen asettanut Joosuan eteen – siihen yhteen kiveen päin on seitsemän silmää! Katso, kaiverran kaiverrukset siihen – tämä on Herran Sebaotin sana – ja otan pois tämän maan pahat teot yhtenä päivänä.',
        10: 'Sinä päivänä – tämä on Herran Sebaotin sana – te kutsutte kukin ystävänne viinipuun ja viikunapuun alle."',
    },
    4: {
        1: 'Herran enkeli, joka oli puhutellut minua, palasi ja herätti minut, niin kuin joku herätetään unestaan.',
        2: 'Hän sanoi minulle: "Mitä sinä näet?" Vastasin: "Näen, katso: lampunjalka, kokonaan kultaa, ja sen yläpuolella öljyastia, ja lampunjalassa seitsemän lamppua, ja seitsemän öljyputkea lamppuihin, jotka ovat siinä ylinnä.',
        3: 'Näen myös kaksi öljypuuta sen vieressä, toinen öljyastian oikealla ja toinen vasemmalla puolella."',
        4: 'Lausuin ja sanoin enkelille, joka puhutteli minua näin: "Mitä nämä ovat, herra?"',
        5: 'Enkeli, joka puhutteli minua, vastasi ja sanoi minulle: "Etkö tiedä, mitä ne ovat?" Sanoin: "En, herra."',
        6: 'Niin hän vastasi ja sanoi minulle näin: "Tämä on Herran sana Serubbaabelille, näin kuuluva: Ei sotaväellä eikä voimalla, vaan minun Hengelläni, sanoo Herra Sebaot.',
        7: 'Mikä olet sinä, suuri vuori? Serubbaabelin edessä sinä olet lakeus. Hän on paneva paikoilleen ylimmän kiven huutojen kaikuessa: \'Suosio, suosio sille!\'"',
        8: 'Sitten minulle tuli tämä Herran sana:',
        9: '"Serubbaabelin kädet ovat tämän temppelin perustaneet, ja hänen kätensä saattavat sen valmiiksi. Niin sinä tulet tietämään, että Herra Sebaot on lähettänyt minut teidän luoksenne.',
        10: 'Sillä kuka pitää halpana pienten alkujen päivän, kun nuo seitsemän Herran silmää, jotka tarkastelevat koko maata, iloitsevat nähdessään luotilangan Serubbaabelin kädessä?"',
        11: 'Lausuin ja sanoin hänelle: "Mitä ovat nämä kaksi öljypuuta lampunjalan oikealla ja vasemmalla puolella?"',
        12: 'Lausuin ja sanoin hänelle toistamiseen: "Mitä ovat nuo kaksi öljypuun oksaa kahden kultaisen putken kohdalla, jotka vuodattavat sisältään kultaa?"',
        13: 'Hän sanoi minulle näin: "Etkö tiedä, mitä ne ovat?" Vastasin: "En, herra."',
        14: 'Hän sanoi: "Nämä ovat ne molemmat öljyllä voidellut, jotka seisovat kaiken maan Herran edessä."',
    },
    5: {
        1: 'Nostin jälleen silmäni, ja katso, oli lentävä kirjakäärö.',
        2: 'Hän sanoi minulle: "Mitä sinä näet?" Vastasin: "Minä näen lentävän kirjakäärön, kaksikymmentä kyynärää pitkän ja kymmenen kyynärää leveän."',
        3: 'Hän sanoi minulle: "Tämä on kirous, joka lähtee yli koko maan. Sillä tämän kirouksen mukaisesti siitä puhdistetaan pois jokainen varas, ja jokainen vannoskelija puhdistetaan siitä pois.',
        4: 'Lasken sen irti – tämä on Herran Sebaotin sana – ja se menee varkaan kotiin ja sen kotiin, joka vannoo väärin nimeeni. Se jää sisälle hänen kotiinsa ja kalvaa sen loppuun asti, sekä sen puut että sen kivet."',
        5: 'Enkeli, joka oli puhutellut minua, lähti liikkeelle ja sanoi minulle: "Nosta silmäsi ja katso: mikä tuo on, joka lähtee liikkeelle?"',
        6: 'Kysyin: "Mikä se on?" Niin hän vastasi: "Tämä on eefa-mitta, joka lähtee liikkeelle." Hän sanoi: "Tämän näköisiä ne ovat koko maan päällä".',
        7: 'Niin katso, lyijykansi kohosi, ja eräs nainen istui eefa-mitan sisällä.',
        8: 'Enkeli sanoi: "Tämä on jumalattomuus." Hän heitti hänet sisälle eefa-mittaan ja paiskasi lyijypainon sen suulle.',
        9: 'Kun nostin silmäni, näin, katso, kaksi naista lähti liikkeelle, ja heillä oli tuulta siivissään, ja niiden siivet olivat kuin haikaran siivet. Ja he kantoivat eefa-mittaa taivaan ja maan välillä.',
        10: 'Sanoin enkelille, joka oli puhutellut minua: "Mihin he kuljettavat eefa-mittaa?"',
        11: 'Hän vastasi minulle: "He menevät rakentamaan sille taloa Sinearin maahan. Kun se on valmis, lasketaan se sinne paikalleen."',
    },
    6: {
        1: 'Nostin jälleen silmäni ja näin, katso, neljät vaunut, jotka lähtivät liikkeelle kahden vuoren välistä, ja vuoret olivat vaskivuoria.',
        2: 'Ensimmäisten vaunujen edessä olivat punaruskeat hevoset, toisten vaunujen edessä olivat mustat hevoset,',
        3: 'kolmansien vaunujen edessä olivat valkoiset hevoset, ja neljänsien vaunujen edessä olivat täplikkäät, väkevät hevoset.',
        4: 'Lausuin ja sanoin enkelille, joka oli puhutellut minua: "Mitä nämä ovat, herra?"',
        5: 'Enkeli vastasi ja sanoi minulle: "Ne ovat neljä taivaan tuulta, jotka lähtevät liikkeelle seisottuaan kaiken maan Herran edessä.',
        6: 'Ne, joiden edessä ovat mustat hevoset, lähtevät pohjoiseen maahan, ja valkoiset lähtevät niiden perään. Täplikkäät lähtevät eteläiseen maahan.',
        7: 'Väkevät ovat lähdössä. Ne ovat innokkaita kiertelemään maata." Hän sanoi: "Menkää kiertelemään maata", ja ne kiertelivät maata.',
        8: 'Hän huusi minua ja sanoi minulle näin: "Katso, ne, jotka lähtivät pohjoiseen maahan, saattavat Henkeni lepäämään pohjoisessa maassa."',
        9: 'Minulle tuli tämä Herran sana ja se kuului:',
        10: '"Ota vastaan karkotuksessa eläviltä Heldailta, Tobialta ja Jedajalta – mene tänä päivänä, mene Joosian, Sefanjan pojan, taloon, johon he ovat tulleet Baabelista –',
        11: 'ja ota vastaan hopea ja kulta, tee kruunu ja pane se ylimmäisen papin Joosuan, Joosadakin pojan, päähän',
        12: 'ja sano hänelle näin: "Näin sanoo Herra Sebaot: Katso, mies nimeltä Vesa! Omalta pohjaltaan hän on kasvava, ja hän on rakentava Herran temppelin.',
        13: 'Herran temppelin hän on rakentava, ja valtasuuruutta hän on kantava, ja hän on istuva ja hallitseva valtaistuimellaan. Hän on oleva pappi valtaistuimellaan, ja rauhan neuvo on vallitseva niiden molempien kesken.',
        14: 'Mutta kruunu on oleva muistona Herran temppelissä Helemistä, Tobiasta ja Jedajasta sekä Sefanjan pojan suosiollisuudesta.',
        15: 'Kaukana asuvat tulevat ja rakentavat Herran temppeliä. Tulette tietämään, että Herra Sebaot on lähettänyt minut luoksenne. Näin tapahtuu, jos te todella kuulette Herran, Jumalanne, ääntä."',
    },
    7: {
        1: 'Kuningas Daarejaveksen neljäntenä vuotena tuli Herran sana Sakarjalle, neljäntenä päivänä yhdeksännessä kuussa, kislev-kuussa.',
        2: 'Beetel oli lähettänyt Sareserin ja Regem-Melekin miehineen rukoilemaan Herran kasvojen edessä',
        3: 'ja kysymään Herran Sebaotin temppelin papeilta ynnä profeetoilta näin: "Onko minun viidennessä kuussa itkettävä ja noudatettava pidättyvyyttä, niin kuin olen tehnyt jo monina vuosina?"',
        4: 'Minulle tuli tämä Herran Sebaotin sana:',
        5: '"Sano kaikelle maan kansalle ja papeille näin: Kun olette paastonneet ja valittaneet viidennessä ja seitsemännessä kuussa, ja jo seitsemänäkymmenenä vuotena, niin minulleko olette paastonne paastonneet?',
        6: 'Kun olette syöneet ja juoneet, niin ettekö ole itsellenne syöneet ja juoneet?',
        7: 'Eikö niin: pitäkää ne sanat, jotka Herra on julistanut aikaisempien profeettojen kautta, kun Jerusalem vielä oli asuttuna ja levossa kuten myös sen ympärillä olevat kaupungit, ja Etelämaa ja Alankomaa olivat asuttuja?"',
        8: 'Sakarjalle tuli tämä Herran sana ja se kuului:',
        9: '"Näin sanoo Herra Sebaot: Tuomitkaa oikea tuomio, tehkää laupeus ja olkaa armollisia kukin veljellenne,',
        10: 'leskeä, orpoa, muukalaista ja köyhää älkää sortako älkääkä miettikö mielessänne pahaa toinen toisellenne.',
        11: 'Mutta he kieltäytyivät ottamasta vaarin ja käänsivät uppiniskaisina selkänsä ja kovettivat korvansa, etteivät kuulisi.',
        12: 'He tekivät sydämensä kovaksi kuin timantti, etteivät kuulisi lakia eivätkä niitä sanoja, jotka Herra Sebaot oli lähettänyt Hengellään entisten profeettojen kautta. Herralta Sebaotilta on tullut suuri viha.',
        13: 'Samoin kuin hän julisti heille, mutta he eivät kuulleet, samoin he huutavat minulle, mutta en kuule, sanoo Herra Sebaot.',
        14: 'Minä karkotan myrskynä heidät kaikkien pakanakansojen sekaan, joita he eivät tunne, ja maa jää autioksi heidän jälkeensä menijöistä ja tulijoista. Ihanan maan he tekevät autioksi."',
    },
    8: {
        1: 'Tuli tämä Herran Sebaotin sana:',
        2: '"Näin sanoo Herra Sebaot: Olen kiivaillut Siionin puolesta suurella kiivaudella, suurella vihalla olen sen puolesta kiivaillut.',
        3: 'Näin sanoo Herra: Käännyn jälleen Siionin puoleen ja tulen asumaan Jerusalemin keskelle, ja Jerusalemia kutsutaan "Totuuden kaupungiksi" ja Herran Sebaotin vuorta "Pyhäksi vuoreksi".',
        4: 'Näin sanoo Herra Sebaot: Vielä on Jerusalemin toreilla istuva vanhuksia, miehiä ja naisia. Kullakin on sauvansa kädessään päivien paljouden vuoksi.',
        5: 'Silloin kaupungin torit tulevat olemaan täynnä nuoria poikia ja tyttöjä, jotka leikkivät sen toreilla.',
        6: 'Näin sanoo Herra Sebaot: Jos tämä onkin ihmeellistä tämän kansan jäännöksen silmissä niinä päivinä, onko se ihmeellistä myös minun silmissäni? – Tämä on Herran Sebaotin sana.',
        7: 'Näin sanoo Herra Sebaot: Katso, olen vapauttava kansani auringon nousun maasta ja laskun maasta.',
        8: 'Tuon heidät asumaan Jerusalemin keskelle. Niin he ovat kansani, ja minä olen heidän Jumalansa totuudessa ja vanhurskaudessa.',
        9: 'Näin sanoo Herra Sebaot: Olkoot kätenne vahvat, teidän, jotka näinä päivinä olette kuulleet nämä sanat profeettojen suusta, sinä päivänä, jona laskettiin Herran Sebaotin huoneen, rakennettavan temppelin, perustus.',
        10: 'Sillä näiden päivien edellä ei saatu palkkaa ihmisen työstä, ei palkkaa eläinten työstä, eikä menijällä eikä tulijalla ollut rauhaa viholliselta, ja lähetin kaikki ihmiset toistensa kimppuun.',
        11: 'Nyt en ole tämän kansan jäännökselle samanlainen, kuin minä olin entisinä päivinä. – Tämä on Herran Sebaotin sana. –',
        12: 'Sillä rauhan kylvö kylvetään, viiniköynnös antaa hedelmänsä, maa antaa satonsa, taivas antaa kasteensa, ja tämän kansan jäännökselle annan perintöosaksi kaiken tämän.',
        13: 'Niin kuin olette olleet kirouksena pakanakansojen seassa, te Juudan heimo ja Israelin heimo, niin te, kun teidät pelastan, tulette olemaan siunauksena. Älkää pelätkö, olkoot kätenne vahvat.',
        14: 'Sillä näin sanoo Herra Sebaot: Niin kuin aioin tehdä teille pahaa, kun teidän isänne vihoittivat minut, sanoo Herra Sebaot, enkä sitä katunut,',
        15: 'niin näinä päivinä sen sijaan minulla on mielessä tehdä hyvää Jerusalemille ja Juudan heimolle. Älkää pelätkö.',
        16: 'Näitä te tehkää: Puhukaa totuutta toinen toisellenne. Tuomitkaa porteissanne oikein, tuomitkaa rauhan tuomio.',
        17: 'Älkää hautoko mielessänne pahaa toinen toisellenne älkääkä rakastako väärää valaa. Sillä kaikkia näitä minä vihaan. Tämä on Herran sana."',
        18: 'Minulle tuli tämä Herran Sebaotin sana ja se kuului:',
        19: '"Näin sanoo Herra Sebaot: Neljännen kuun paasto, viidennen paasto, seitsemännen paasto ja kymmenennen paasto on oleva Juudan heimolle ilo ja riemu ja mieluinen juhla. Mutta rakastakaa totuutta ja rauhaa.',
        20: 'Näin sanoo Herra Sebaot: Vielä tulee kansoja, monien kaupunkien asukkaita,',
        21: "ja toisen asukkaat menevät toiseen kaupunkiin ja sanovat: 'Lähtekäämme rukoilemaan Herran edessä ja etsimään Herraa Sebaotia.' – 'Minäkin lähden.'",
        22: 'Niin monet kansat, väkevät pakanakansat, tulevat Jerusalemiin etsimään Herraa Sebaotia, etsimään Herran kasvoja.',
        23: 'Näin sanoo Herra Sebaot: Niinä päivinä tarttuu kymmenen miestä kaikista pakanakansojen kielistä, tarttuu Juudan miestä liepeeseen sanoen: \'Me tahdomme kulkea teidän kanssanne, sillä olemme kuulleet, että Jumala on teidän kanssanne.\'"',
    },
    9: {
        1: 'Profeettasana, Herran sana, Hadrakin maata vastaan, ja Damaskossa se viipyy. Sillä Herran silmä katsoo ihmisiä, kaikkia Israelin sukukuntia,',
        2: 'myös Hamatia, joka on sen kanssa rajanaapurina, sekä Tyyroa ja Siidonia, sillä ne ovat hyvin viisaat.',
        3: 'Tyyro on rakentanut itselleen linnoituksia ja kasannut kokoon hopeaa kuin tomua ja kultaa kuin katujen lokaa.',
        4: 'Katso, Herra köyhdyttää sen ja syöksee mereen sen voiman, ja se itse poltetaan tulella.',
        5: 'Sen näkee Askelon ja pelästyy, ja Gassa, ja vapisee kovin, ja Ekron, sillä sen toivo joutuu häpeään. Gassasta menehtyy kuningas, eikä Askelonissa enää asuta.',
        6: 'Asdodissa asuu sekakansaa, ja hävitän filistealaisten ylpeyden.',
        7: 'Poistan veret hänen suustaan ja heidän iljetyksensä hänen hampaittensa välistä, ja hänestäkin jää jäännös Jumalallemme. Hän on oleva kuin sukuruhtinas Juudassa, ja Ekron on oleva kuin jebusilainen.',
        8: 'Teen leirini temppelini suojaksi sotajoukoilta, jotka tulevat ja menevät, eikä sortaja tule enää heidän kimppuunsa, sillä nyt olen katsellut sitä omin silmin.',
        9: 'Iloitse suuresti, tytär Siion, riemuitse, tytär Jerusalem, sillä kuninkaasi tulee sinulle! Vanhurskas ja auttaja hän on, on nöyrä ja ratsastaa aasilla, aasintamman varsalla.',
        10: 'Hävitän vaunut Efraimista ja hevoset Jerusalemista. Sodan jousi hävitetään, ja hän julistaa rauhan kansoille. Hänen hallituksensa ulottuu merestä mereen ja virralta hamaan maan ääriin.',
        11: 'Myös vankisi päästän pois vedettömästä kuopasta liittosi verellä.',
        12: 'Palatkaa linnoitukseen, te vangit, joilla on toivo. Myös tänä päivänä julistan: kaksin verroin sinulle korvaan.',
        13: 'Sillä jännitän Juudan jousekseni, panen siihen nuoleksi Efraimin ja nostan poikasi, Siion, poikiasi vastaan, Jaavan, ja teen sinut sankarin miekan kaltaiseksi.',
        14: 'Herra näkyy heidän yllään, ja hänen nuolensa lähtee kuin salama. Herra, Herra puhaltaa torveen ja kulkee etelän myrskytuulissa.',
        15: 'Tapahtuu myös, että Herra Sebaot suojelee heitä, ja he syövät ja he tallaavat linkokiviä, he juovat ja pauhaavat kuin viiniä nauttineet ja ovat täynnä kuin uhrimaljat, kuin alttarin kulmat.',
        16: 'Herra, heidän Jumalansa, on sinä päivänä pelastava heidät, kansansa, joka on kuin hänen lammaslaumansa. He näet ovat kruunuun kiinnitettyjä kiviä, korotettuja hänen maansa ylle.',
        17: 'Sillä kuinka suuri onkaan oleva heidän onnensa ja heidän ihanuutensa: vilja saa kasvamaan nuorukaiset ja rypälemehu neitsyet!',
    },
    10: {
        1: 'Rukoilkaa Herralta sadetta kevätsateen aikaan: Herra tekee ukkospilvet ja antaa heille sadekuurot, antaa kasvit jokaisen pellolle.',
        2: 'Sillä kotijumalat puhuvat jumalattomuutta, ja tietäjät näkevät petollisia näkyjä, puhuvat valheunia ja turhia sanoja. Sen tähden he saavat lähteä matkaan kuin lammaslauma ja kärsiä vaivaa, koska ei ole paimenta.',
        3: 'Paimenia kohtaan on syttynyt vihani, ja rankaisen vuohipukkeja, sillä Herra Sebaot pitää huolen laumastaan, Juudan heimosta, ja asettaa sen ikään kuin kunniaratsukseen sodassa.',
        4: 'Siitä on lähtevä kulmakivi, siitä kiinnityspaalu, siitä sotajousi, siitä lähtevät kaikki käskijät.',
        5: 'He ovat kuin sankarit, jotka polkevat katujen lokaa sodassa. He sotivat, sillä Herra on heidän kanssaan, ja häpeään joutuvat hevosilla ratsastajat.',
        6: 'Teen voimakkaaksi Juudan heimon ja pelastan Joosefin heimon. Palautan heidät, sillä armahdan heitä, ja he tulevat olemaan, kuin en olisi heitä hylännytkään. Sillä minä olen Herra, heidän Jumalansa, ja kuulen heidän rukouksensa.',
        7: 'Efraim on oleva kuin sankari, ja heidän sydämensä on iloitseva kuin viinistä. Heidän lapsensa näkevät sen ja iloitsevat; heidän sydämensä riemuitsee Herrassa.',
        8: 'Olen viheltävä heille ja kokoava heidät, sillä lunastan heidät, ja he lisääntyvät, niin kuin lisääntyivät ennen.',
        9: 'Kun sirottelen heitä kansojen sekaan, he muistavat minut kaukaisissa maissa, ja he elävät lastensa kanssa ja palaavat takaisin.',
        10: 'Tuon heidät takaisin Egyptin maasta ja kokoan heidät Assurista. Vien heidät Gileadin maahan ja Libanonille, eikä heille ole riittävästi tilaa.',
        11: 'Hän käy ahdistuksen meren halki, hän lyö meren aaltoja, ja kaikki Niilivirran syvyydet kuivuvat, Assurin ylpeys painuu alas, ja Egyptin valtikka väistyy.',
        12: 'Mutta heidät teen voimakkaiksi Herrassa, ja he vaeltavat hänen nimessään. Tämä on Herran sana.',
    },
    11: {
        1: 'Avaa ovesi, Libanon! Tuli on kuluttava setrisi.',
        2: 'Vaikertakoon sypressi, sillä setri on kaatunut. Hävitetyt ovat nuo mahtavat. Valittakaa, te Baasanin tammet, sillä luoksepääsemätön metsä on sortunut.',
        3: 'Kuule paimenten valitusta, kun heidän mahtavansa on hävitetty. Kuule nuorten leijonien karjahtelua, kun Jordanin ylpeys on hävitetty.',
        4: 'Näin sanoi Herra, Jumalani:',
        5: '"Kaitse teuraslampaita, joita niiden ostajat teurastavat tuntematta syyllisyyttä, ja joista niiden myyjät sanovat: \'Kiitetty olkoon Herra, olen rikastunut\', ja joita niiden paimenet eivät sääli.',
        6: 'Sillä en enää säästä maan asukkaita. Tämä on Herran sana. Katso, annan ihmisten joutua toistensa käsiin ja kuninkaansa käsiin, ja he hävittävät maan, enkä pelasta ketään heidän käsistään."',
        7: 'Kaitsin teuraslampaita, lampaista kurjimpia. Otin itselleni kaksi sauvaa. Nimitin toisen "Suloudeksi", toisen nimitin "Yhteydeksi", ja kaitsin lampaita.',
        8: 'Hävitin kolme paimenta yhtenä kuukautena, mutta sieluni kävi kärsimättömäksi lampaille, ja heidänkin sielunsa kääntyi minusta pois.',
        9: 'Sanoin: "En kaitse teitä enää. Kuolkoon, joka kuolee. Hävitköön, joka häviää, ja jäljellejäävät syökööt toistensa lihaa."',
        10: 'Otin sauvani Sulouden ja katkaisin sen purkaakseni liittoni, jonka olin tehnyt kaikkien kansojen kanssa.',
        11: 'Sinä päivänä se purkautui, ja lampaista kurjimmat, jotka ottivat minusta vaarin, tulivat tietämään, että se oli Herran sana.',
        12: 'Sanoin heille: "Jos teille hyväksi näkyy, antakaa minulle palkkani; jollei, niin olkaa antamatta." He punnitsivat palkakseni kolmekymmentä hopearahaa.',
        13: 'Herra sanoi minulle: "Heitä se savenvalajalle, tuo kallis hinta, jonka arvoiseksi he ovat minut arvioineet." Otin ne kolmekymmentä hopearahaa ja heitin ne Herran huoneeseen savenvalajalle.',
        14: 'Sitten katkaisin toisen sauvani, Yhteyden, purkaakseni veljeyden Juudan ja Israelin väliltä.',
        15: 'Herra sanoi minulle: "Ota vielä itsellesi hullun paimenen kapineet.',
        16: 'Sillä katso, minä olen herättävä maahan paimenen: kadonneesta hän ei pidä huolta, hajaantunutta hän ei etsi, ruhjoutunutta hän ei paranna, pystyssä pysyvää hän ei tue. Mutta hän syö lihavien lihaa ja halkaisee niiden sorkat.',
        17: 'Voi hullua paimenta, joka lampaat hylkää! Käyköön miekka hänen käsivarteensa ja oikeaan silmäänsä. Hänen käsivartensa kuivettukoon, ja hänen oikea silmänsä soetkoon."',
    },
    12: {
        1: 'Profeettasana. Herran sana Israelista. Tämä on Herran sana. Hän on jännittänyt taivaan ja perustanut maan sekä luonut ihmisen hengen hänen sisimpäänsä.',
        2: 'Katso, minä teen Jerusalemin maljaksi, joka panee kaikki kansat horjumaan sen ympärillä, ja myös Juudalle se on tuleva, kun Jerusalemia piiritetään.',
        3: 'Sinä päivänä tapahtuu, että teen Jerusalemin raskaaksi kiveksi kaikille kansoille. Kaikki, jotka sitä nostavat, telovat itsensä; ja kaikki maan kansakunnat kokoontuvat sitä vastaan.',
        4: 'Sinä päivänä – tämä on Herran sana – lyön kaikki hevoset vauhkoudella ja niiden ratsastajat hulluudella. Mutta Juudan heimoa kohti avaan silmäni, ja kaikki kansojen hevoset lyön sokeudella.',
        5: 'Silloin Juudan sukuruhtinaat sanovat sydämessään: "Minun väkevyyteni ovat Jerusalemin asukkaat Herrassa Sebaotissa, heidän Jumalassaan."',
        6: 'Sinä päivänä teen Juudan sukuruhtinaat ikään kuin tulipannuksi puiden sekaan ja ikään kuin tulisoihduksi lyhteiden sekaan, ja he kuluttavat oikealta ja vasemmalta, kuluttavat kaikki kansat ympäriltään. Jerusalem asuu yhä paikoillaan Jerusalemissa.',
        7: 'Herra on ensiksi pelastava Juudan telttamajat, ettei Daavidin suvun kunnia ja Jerusalemin asukkaiden kunnia ylvästelisi Juudaa vastaan.',
        8: 'Sinä päivänä Herra suojaa Jerusalemin asukkaita. Se, joka heistä kompastuu, on sinä päivänä oleva kuin Daavid, ja Daavidin huone on oleva kuin Jumala, kuin Herran Enkeli heidän edessään.',
        9: 'Mutta tapahtuu, että sinä päivänä minä hävitän kaikki pakanakansat, jotka hyökkäävät Jerusalemia vastaan.',
        10: 'Vuodatan Daavidin huoneen päälle ja Jerusalemin asukkaiden päälle armon ja rukouksen Hengen. He katsovat minuun, jonka ovat lävistäneet. He valittavat häntä, niin kuin valitetaan ainoaa poikaa, murehtivat häntä katkerasti, niin kuin katkerasti murehditaan esikoista.',
        11: 'Sinä päivänä pidetään Jerusalemissa suuret valittajaiset, niin kuin olivat Hadadrimmonin valittajaiset Megiddon laaksossa.',
        12: 'Maa pitää valittajaisia, kukin sukukunta erikseen: Daavidin huoneen sukukunta erikseen ja heidän naisensa erikseen, Naatanin huoneen sukukunta erikseen ja heidän naisensa erikseen,',
        13: 'Leevin huoneen sukukunta erikseen ja heidän naisensa erikseen, siimeiläisten sukukunta erikseen ja heidän naisensa erikseen. Kaikki muut sukukunnat, kukin sukukunta erikseen ja heidän naisensa erikseen.',
    },
    13: {
        1: 'Sinä päivänä on Daavidin suvulla ja Jerusalemin asukkailla oleva avoin lähde syntiä ja saastaisuutta vastaan.',
        2: 'Sinä päivänä tapahtuu – tämä on Herran Sebaotin sana – että hävitän epäjumalien nimet maasta, eikä niitä enää muisteta. Myös profeetat ja saastaisuuden hengen karkotan maasta.',
        3: 'Jos joku vielä ennustaa, hänen isänsä ja äitinsä, hänen vanhempansa, sanovat hänelle: "Sinä et saa elää, koska olet puhunut valhetta Herran nimeen." Hänen isänsä ja äitinsä, hänen vanhempansa, lävistävät hänet hänen ennustamisensa tähden.',
        4: 'Sinä päivänä tapahtuu, että profeetat häpeävät kukin näkyään, kun he ennustavat, eivätkä he valehdellakseen pue päälleen karvaista viittaa.',
        5: 'Hän sanoo: "En ole profeetta, vaan peltomies, sillä eräs mies on ostanut minut orjaksi jo nuoruudessani."',
        6: 'Jos häneltä kysytään: "Mitä ovat nuo haavat käsissäsi?" hän vastaa: "Ne lyötiin rakkaitten ystävieni huoneessa."',
        7: 'Herää, miekka, paimentani vastaan ja lähintä miestäni vastaan. Tämä on Herran Sebaotin sana. Lyö paimenta, ja joutukoot lampaat hajalle, mutta käännän jälleen käteni pienimpiä kohden.',
        8: 'Näin on käyvä koko maassa. – Tämä on Herran sana. – Kaksi osaa siitä hävitetään ja saa surmansa, mutta kolmas osa siitä jää jäljelle.',
        9: 'Kolmannen osan vien tuleen. Sulatan heidät, kuin hopea sulatetaan, ja koettelen heitä, niin kuin kultaa koetellaan. He huutavat avuksi nimeäni, ja vastaan heille. Sanon: "Se on kansani", ja se sanoo: " Herra, Jumalani."',
    },
    14: {
        1: 'Katso, Herran päivä tulee, ja saaliisi jaetaan keskelläsi.',
        2: 'Kokoan kaikki pakanat sotaan Jerusalemia vastaan. Kaupunki valloitetaan, talot ryöstetään, naiset raiskataan, ja puoli kaupunkia lähtee karkotukseen, mutta jäljelle jäävää kansaa ei hävitetä kaupungista.',
        3: 'Herra lähtee liikkeelle ja sotii näitä pakanoita vastaan, niin kuin sodan käyntinsä päivänä, taistelun päivänä.',
        4: 'Hänen jalkansa seisovat sinä päivänä Öljymäellä, joka on Jerusalemin edustalla itää kohti. Öljymäki halkeaa kahtia idästä länteen hyvin suureksi laaksoksi: toinen puoli mäkeä siirtyy pohjoiseen ja toinen puoli etelään.',
        5: 'Mutta te pakenette mäkieni väliseen laaksoon, sillä mäkien välinen laakso ulottuu Asaliin asti. Te pakenette, niin kuin pakenitte maanjäristystä Ussian, Juudan kuninkaan, päivinä. Herra, Jumalani, tulee ja kaikki pyhät kanssasi.',
        6: 'Tapahtuu, ettei sinä päivänä ole valoa. Pimeys sammuttaa valon.',
        7: 'Se on oleva yksi päivä – Herran tuntema. Ei ole päivää eikä yötä, ja ehtoolla on oleva valoisaa.',
        8: 'Tapahtuu, että sinä päivänä elävät vedet virtaavat Jerusalemista: toiset puolet niistä Idänmerta kohti, toiset puolet Länsimerta kohti. Niin tapahtuu kesällä ja talvella.',
        9: 'Herra on oleva koko maan kuningas. Sinä päivänä on Herra oleva yksi ja hänen nimensä yksi.',
        10: 'Koko maa muuttuu tasaiseksi kuin Aromaa Gebasta Rimmoniin asti Jerusalemin eteläpuolelle. Tämä on oleva korkea ja asuttu paikallaan Benjaminin portista entisen portin kohdalle asti, Kulmaporttiin ja Hananelin tornilta kuninkaan viinikuurniin asti.',
        11: 'He asuvat siellä, eikä sitä enää hävitetä, ja Jerusalem on oleva asuttu ja turvassa.',
        12: 'Mutta tämä on oleva vitsaus, jolla Herra rankaisee niitä kansoja, jotka sotivat Jerusalemia vastaan: hän mädättää siltä kansalta lihan, kun se vielä seisoo jaloillaan, sen silmät mätänevät kuopissaan, ja sen kieli mätänee sen suussa.',
        13: 'Sinä päivänä on tuleva Herralta suuri hämminki heidän keskelleen, niin että he käyvät kiinni toinen toisensa käteen ja toisen käsi kohoaa toisen kättä vastaan.',
        14: 'Myös Juuda on sotiva Jerusalemissa, ja kaikkien pakanakansojen rikkaudet kootaan joka taholta: kullat ja hopeat ja hyvin paljon vaatteita.',
        15: 'Samoin on vitsaus kohtaava hevosia, muuleja, kameleja, aaseja ja kaikkea karjaa, mitä niissä leireissä on – kaikkia samanlainen vitsaus.',
        16: 'Mutta tapahtuu, että kaikki niiden pakanakansojen tähteet, jotka ovat hyökänneet Jerusalemia vastaan, nousevat vuosi vuodelta sinne kumartaen rukoilemaan kuningasta, Herraa Sebaotia, ja viettämään lehtimajanjuhlaa.',
        17: 'Tapahtuu, että niille maan sukukunnille, jotka eivät nouse Jerusalemiin kumartaen rukoilemaan kuningasta, Herraa Sebaotia, ei tule sadetta.',
        18: 'Mutta jos egyptiläisten sukukunta ei nouse eikä tule sinne ylös, ei tule sitä heillekään, vaan heitä on kohtaava se vitsaus, millä Herra rankaisee niitä pakanakansoja, jotka eivät nouse sinne viettämään lehtimajanjuhlaa.',
        19: 'Tämä on oleva egyptiläisten synnin rangaistus ja kaikkien niiden pakanakansojen synnin rangaistus, jotka eivät nouse sinne viettämään lehtimajanjuhlaa.',
        20: 'Sinä päivänä lukee hevosten kulkusissa: "Pyhitetty Herralle." Padat Herran temppelissä ovat uhrimaljojen vertaisia, jotka ovat alttarin edessä.',
        21: 'Silloin jokainen pata Jerusalemissa ja Juudassa on oleva pyhä Herralle Sebaotille, ja kaikki uhraajat tulevat ja ottavat niitä ja keittävät niissä. Eikä sinä päivänä ole enää yhtään kaupustelijaa Herran Sebaotin temppelissä.',
    },
}
